// Package: ModelContextProtocol
using ModelContextProtocol.Server;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register backend services the MCP tools will resolve
builder.Services.AddSingleton<IProductRepository, InMemoryProductRepository>();

// Configure the MCP server with stdio transport
builder.Services.AddMcpServer()
    .WithTools<ProductTools>()
    .WithStdioTransport();

var app = builder.Build();
await app.RunAsync();
// Expected: server starts, listens on stdin/stdout, client discovers tools via MCP handshake
